css:
.bf-guide { color: #2b3345; }

.bf-hero {
  background: linear-gradient(135deg, #33489e 0%, #4f6fe0 55%, #7b93ef 100%);
  border-radius: 16px;
  padding: 40px 44px;
  color: #fff;
  margin-bottom: 28px;
  position: relative;
  overflow: hidden;
}
.bf-badge {
  display: inline-block;
  background: rgba(255,255,255,.16);
  border: 1px solid rgba(255,255,255,.35);
  padding: 4px 12px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .07em;
  text-transform: uppercase;
  margin-bottom: 14px;
}
.bf-hero h1 { font-size: 32px; font-weight: 800; margin: 0 0 10px; line-height: 1.2; }
.bf-hero p { font-size: 15px; opacity: .92; margin: 0; max-width: 640px; line-height: 1.55; }

.bf-tabs {
  display: flex;
  gap: 28px;
  border-bottom: 1px solid #e3e7ef;
  margin-bottom: 30px;
  flex-wrap: wrap;
}
.bf-tab {
  background: none;
  border: none;
  padding: 12px 2px;
  font-size: 14px;
  font-weight: 600;
  color: #697386;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
}
.bf-tab:hover { color: #3b5fe0; }
.bf-tab.active { color: #3b5fe0; border-bottom-color: #3b5fe0; }

.bf-panel { display: none; }
.bf-panel.active { display: block; }

.bf-panel h2 { font-size: 22px; font-weight: 800; margin: 0 0 14px; }
.bf-panel h3 { font-size: 15.5px; font-weight: 700; margin: 26px 0 12px; }
.bf-panel p { color: #4b5566; line-height: 1.65; margin: 0 0 12px; }

.bf-flow { display: flex; align-items: center; flex-wrap: wrap; gap: 10px; margin: 14px 0 26px; }
.bf-chip {
  background: #fff;
  border: 1px solid #dbe3f7;
  color: #2149c9;
  font-weight: 700;
  font-size: 13.5px;
  padding: 10px 16px;
  border-radius: 10px;
  white-space: nowrap;
}
.bf-arrow { color: #aab3c5; font-size: 16px; }

.bf-cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 14px; margin: 14px 0 26px; }
.bf-card { border: 1px solid #e7eaf1; border-radius: 12px; padding: 16px 18px; background: #fbfcfe; }
.bf-card h4 { margin: 0 0 6px; font-size: 14px; font-weight: 700; color: #1f2530; }
.bf-card p { margin: 0; font-size: 13px; color: #5c6577; line-height: 1.55; }

.bf-steps { counter-reset: step; list-style: none; padding: 0; margin: 14px 0 26px; }
.bf-steps li {
  position: relative;
  padding: 4px 0 4px 40px;
  margin-bottom: 12px;
  color: #3d4657;
  line-height: 1.6;
}
.bf-steps li::before {
  counter-increment: step;
  content: counter(step);
  position: absolute;
  left: 0;
  top: 2px;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: #3b5fe0;
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
}

table.bf-table { width: 100%; border-collapse: collapse; margin: 14px 0 26px; font-size: 13.5px; }
table.bf-table th {
  text-align: left;
  background: #f5f7fb;
  color: #465066;
  font-weight: 700;
  padding: 10px 12px;
  border-bottom: 2px solid #e7eaf1;
}
table.bf-table td { padding: 10px 12px; border-bottom: 1px solid #eef0f5; color: #3d4657; vertical-align: top; }

.bf-note {
  background: #eef3ff;
  border-left: 3px solid #3b5fe0;
  padding: 12px 16px;
  border-radius: 6px;
  font-size: 13.5px;
  color: #2b3550;
  margin: 10px 0 26px;
}

.bf-badges-row { display: flex; gap: 8px; flex-wrap: wrap; margin: 10px 0 22px; }
.bf-pill { background: #eef1f8; color: #3b4357; padding: 5px 12px; border-radius: 999px; font-size: 12px; font-weight: 600; }

.bf-tag {
  display: inline-block;
  background: #f0f3fb;
  color: #4a5578;
  border: 1px solid #dde3f2;
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .02em;
  white-space: nowrap;
}

@media (max-width: 640px) {
  .bf-hero { padding: 28px 22px; }
  .bf-hero h1 { font-size: 24px; }
}

javascript:
document.addEventListener('DOMContentLoaded', function () {
	var tabs = document.querySelectorAll('.bf-tab');
	var panels = document.querySelectorAll('.bf-panel');
	tabs.forEach(function (tab) {
		tab.addEventListener('click', function () {
			tabs.forEach(function (t) { t.classList.remove('active'); });
			panels.forEach(function (p) { p.classList.remove('active'); });
			tab.classList.add('active');
			var target = document.querySelector('.bf-panel[data-panel="' + tab.dataset.tab + '"]');
			if (target) target.classList.add('active');
		});
	});
});
